//! Puts the generated files together: the server registry and the client `api`.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write;

use super::parse::Function;
use super::types::{Ty, lua_string};
use super::validator::Validators;

/// Must match `runtime` in the library's protocol. Bump both when generated code
/// and the library stop being compatible.
const RUNTIME: u32 = 1;

const HEADER: &str =
    "--!strict\n-- Generated by rogrid. Do not edit: run `rogrid generate` to update it.\n\n";

/// A request and where its module sits in the game, as a `@game/...` require path.
pub struct Entry {
    pub function: Function,
    pub require_path: String,
}

/// The registry `RoGrid.start` loads: every request with its module and input checker.
pub fn server(entries: &[Entry]) -> String {
    let mut validators = Validators::default();

    // Named types first, so a checker made for an inline input can never take their name.
    // Only inputs are checked, so types that only appear in an output get no checker.
    for entry in entries {
        let needed = input_aliases(&entry.function);
        for (name, ty) in &entry.function.aliases {
            if needed.contains(name.as_str()) {
                validators.alias(name, ty);
            }
        }
    }

    let mut registry = String::new();
    for Entry {
        function,
        require_path,
    } in entries
    {
        let _ = writeln!(registry, "\t\t[{}] = {{", lua_string(&function.name));
        let _ = writeln!(
            registry,
            "\t\t\tdefinition = require({}),",
            lua_string(require_path)
        );
        if let Some(input) = &function.input {
            let _ = writeln!(
                registry,
                "\t\t\tcheck = {},",
                validators.checker(input, &function.name)
            );
        }
        let _ = writeln!(registry, "\t\t}},");
    }

    format!(
        "{HEADER}{}\nreturn {{\n\truntime = {RUNTIME},\n\tfunctions = {{\n{registry}\t}},\n}}\n",
        validators.render()
    )
}

/// The named types a request's input depends on, directly or through other named types.
fn input_aliases(function: &Function) -> BTreeSet<&str> {
    let mut needed = BTreeSet::new();
    let mut pending: Vec<&Ty> = function.input.iter().collect();

    while let Some(ty) = pending.pop() {
        match ty {
            Ty::Alias(name) => {
                if needed.insert(name.as_str()) {
                    pending.extend(
                        function
                            .aliases
                            .iter()
                            .filter(|(alias, _)| alias == name)
                            .map(|(_, definition)| definition),
                    );
                }
            }
            Ty::Optional(inner) | Ty::Array(inner) | Ty::Map(inner) => pending.push(inner),
            Ty::Table(fields) => pending.extend(fields.iter().map(|(_, field)| field)),
            Ty::Union(members) => pending.extend(members),
            _ => {}
        }
    }

    needed
}

/// The module the client requires: one typed function per request, nested by folder.
pub fn client(entries: &[Entry], library: &str) -> Result<String, String> {
    if entries.is_empty() {
        return Ok(format!("{HEADER}return {{}}\n"));
    }

    let mut out = String::from(HEADER);
    let _ = writeln!(out, "local RoGrid = require({})\n", lua_string(library));

    for entry in entries {
        for (name, ty) in &entry.function.aliases {
            let _ = writeln!(out, "export type {name} = {}", ty.to_luau());
        }
    }

    let mut tree = BTreeMap::new();
    for entry in entries {
        let segments: Vec<&str> = entry.function.name.split('/').collect();
        insert(&mut tree, &segments, &entry.function)?;
    }

    out.push_str("\nlocal caller = RoGrid.runtime.caller\n\nreturn {\n");
    render(&tree, 1, &mut out);
    out.push_str("}\n");
    Ok(out)
}

enum Node<'a> {
    Request(&'a Function),
    Folder(BTreeMap<String, Node<'a>>),
}

fn insert<'a>(
    tree: &mut BTreeMap<String, Node<'a>>,
    segments: &[&str],
    function: &'a Function,
) -> Result<(), String> {
    let clash = || {
        format!(
            "`{}` clashes with another request: a name cannot be both a request and a folder",
            function.name
        )
    };

    let (first, rest) = segments
        .split_first()
        .expect("a request name is never empty");
    if rest.is_empty() {
        return match tree.insert(first.to_string(), Node::Request(function)) {
            None => Ok(()),
            Some(_) => Err(clash()),
        };
    }

    match tree
        .entry(first.to_string())
        .or_insert_with(|| Node::Folder(BTreeMap::new()))
    {
        Node::Folder(children) => insert(children, rest, function),
        Node::Request(_) => Err(clash()),
    }
}

fn render(tree: &BTreeMap<String, Node>, indent: usize, out: &mut String) {
    let pad = "\t".repeat(indent);
    for (name, node) in tree {
        match node {
            Node::Folder(children) => {
                let _ = writeln!(out, "{pad}{name} = {{");
                render(children, indent + 1, out);
                let _ = writeln!(out, "{pad}}},");
            }
            Node::Request(function) => {
                let input = function
                    .input
                    .as_ref()
                    .map_or(String::new(), |ty| format!("input: {}", ty.to_luau()));
                let output = function
                    .output
                    .as_ref()
                    .map_or("()".to_string(), |ty| ty.to_luau());
                // Through `any`, because Luau will not cast between functions of different arity.
                let _ = writeln!(
                    out,
                    "{pad}{name} = (caller({}) :: any) :: ({input}) -> {output},",
                    lua_string(&function.name)
                );
            }
        }
    }
}
